* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  padding: 0;
  background: #fff;
}

body {
  font-family: Inter, "Segoe UI", Arial, sans-serif;
  color: #231F20;
  font-size: 14px;
}

#root {
  height: calc(var(--appsmith-ui-height) * 1px);
  overflow-y: auto;
  overflow-x: hidden;
  padding: 16px 24px 20px;
}

.head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 12px;
}

#tila {
  font-size: 12.5px;
  font-weight: 600;
}

.seg {
  display: inline-flex;
  border: 1px solid #D1D5DB;
  border-radius: 6px;
  overflow: hidden;
}

.seg button {
  border: 0;
  background: #fff;
  padding: 7px 11px;
  font: inherit;
  font-size: 12.5px;
  cursor: pointer;
  color: #4B5563;
}

.seg button.on {
  background: #231F20;
  color: #fff;
}

.seg button:disabled {
  cursor: default;
  opacity: 0.6;
}

.seg button:focus-visible, .btn:focus-visible, input:focus-visible, select:focus-visible {
  outline: 2px solid #B4232A;
  outline-offset: 1px;
}

.lukkopalkki {
  display: flex;
  gap: 12px;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  background: #FEF3C7;
  border: 1px solid #FCD34D;
  border-radius: 8px;
  padding: 8px 12px;
  margin-bottom: 10px;
  font-size: 13px;
}

.rivi {
  border: 1px solid #E3E5E8;
  border-radius: 8px;
  padding: 10px 12px;
  margin-bottom: 8px;
  background: #FAFAFA;
}

.rivi.virhe {
  border-color: #DC2626;
  background: #FEF2F2;
}

.rivi.lukittu {
  background: #F3F4F6;
}

.r1 {
  display: flex;
  gap: 10px;
  align-items: center;
}

.badge {
  flex: 0 0 96px;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  padding: 4px 0;
  text-align: center;
  border-radius: 5px;
  background: #E5E7EB;
  color: #374151;
}

.b-materiaali {
  background: #DBEAFE;
  color: #1E40AF;
}

.b-tyo {
  background: #FEF3C7;
  color: #92400E;
}

.b-kone {
  background: #E0E7FF;
  color: #3730A3;
}

.b-vakio {
  background: #DCFCE7;
  color: #166534;
}

.b-oma {
  background: #F3E8FF;
  color: #6B21A8;
}

.main {
  flex: 1;
  min-width: 0;
  position: relative;
}

.hinta {
  flex: 0 0 118px;
  text-align: right;
  font-weight: 700;
  font-size: 15px;
  font-variant-numeric: tabular-nums;
}

.hinta small {
  display: block;
  font-weight: 400;
  color: #6B7280;
  font-size: 11px;
}

.teot {
  flex: 0 0 78px;
  display: flex;
  gap: 2px;
  justify-content: flex-end;
}

.lukko {
  font-size: 13px;
  padding: 5px 7px;
}

.ic {
  border: 0;
  background: transparent;
  cursor: pointer;
  padding: 5px 6px;
  border-radius: 5px;
  color: #6B7280;
  font-size: 15px;
  line-height: 1;
}

.ic:hover {
  background: #E5E7EB;
  color: #231F20;
}

.r2 {
  display: flex;
  gap: 10px;
  align-items: flex-end;
  flex-wrap: wrap;
  margin: 8px 0 0 106px;
}

.f {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.f label {
  font-size: 11px;
  color: #6B7280;
}

input[type=text], select {
  font: inherit;
  border: 1px solid #D1D5DB;
  border-radius: 6px;
  padding: 6px 8px;
  background: #fff;
  color: #231F20;
}

input:disabled, select:disabled {
  background: #F3F4F6;
  color: #6B7280;
}

input.n {
  width: 78px;
  text-align: right;
  font-variant-numeric: tabular-nums;
}

input.n.s {
  width: 60px;
}

input.w {
  width: 100%;
}

input.tot {
  border-color: #22C55E;
}

input.kate {
  background: #F9FAFB;
  color: #6B7280;
}

input.kate.oma {
  background: #FEF3C7;
  color: #231F20;
  font-weight: 700;
  border-color: #F59E0B;
}

.x {
  align-self: flex-end;
  padding-bottom: 7px;
  color: #9CA3AF;
}

.x.tumma {
  color: #4B5563;
}

.sel {
  margin: 6px 0 0 106px;
  font-size: 12px;
  color: #4B5563;
}

.sel:empty {
  display: none;
}

.sel.varo {
  color: #B45309;
}

.sel.err {
  color: #B91C1C;
  font-weight: 600;
}

.chk {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 12px;
  color: #4B5563;
  padding-bottom: 7px;
  cursor: pointer;
}

.chips {
  display: flex;
  gap: 4px;
  padding-bottom: 3px;
}

.chip {
  border: 1px solid #D1D5DB;
  background: #fff;
  border-radius: 999px;
  padding: 3px 9px;
  font: inherit;
  font-size: 12px;
  cursor: pointer;
  color: #374151;
}

.chip:hover {
  background: #F3F4F6;
}

.dd {
  position: absolute;
  z-index: 20;
  left: 0;
  right: 0;
  top: 100%;
  margin-top: 3px;
  background: #fff;
  border: 1px solid #D1D5DB;
  border-radius: 8px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.14);
  max-height: 300px;
  overflow: auto;
}

.dd .g {
  font-size: 11px;
  font-weight: 700;
  color: #B4232A;
  padding: 7px 10px 3px;
  text-transform: uppercase;
  letter-spacing: 0.03em;
}

.dd .o {
  padding: 6px 10px;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  gap: 10px;
}

.dd .o.act, .dd .o:hover {
  background: #FEE2E2;
}

.dd .o span {
  color: #6B7280;
  font-size: 12px;
  white-space: nowrap;
}

.lisaa {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin: 12px 0 4px;
}

.btn {
  border: 0;
  border-radius: 6px;
  padding: 8px 14px;
  font: inherit;
  font-weight: 600;
  cursor: pointer;
  background: #E0DEDE;
  color: #231F20;
}

.btn:hover {
  filter: brightness(0.95);
}

.btn kbd {
  font: inherit;
  font-weight: 400;
  font-size: 11px;
  opacity: 0.6;
  margin-left: 5px;
}

.tyhja {
  border: 2px dashed #D1D5DB;
  border-radius: 8px;
  padding: 22px;
  text-align: center;
  color: #6B7280;
}

.yht {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 18px;
  margin-top: 14px;
  border-top: 1px solid #E3E5E8;
  padding-top: 14px;
}

.box {
  border: 1px solid #E3E5E8;
  border-radius: 8px;
  padding: 14px 16px;
}

.box h3 {
  margin: 0 0 8px;
  font-size: 12px;
  color: #6B7280;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.03em;
}

.iso {
  font-size: 28px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  line-height: 1.1;
}

.kv {
  display: flex;
  justify-content: space-between;
  font-size: 13px;
  padding: 2px 0;
  color: #374151;
  font-variant-numeric: tabular-nums;
}

.kv.viiva {
  margin-top: 6px;
  border-top: 1px solid #E3E5E8;
  padding-top: 6px;
}

.pill {
  display: inline-block;
  font-size: 11px;
  font-weight: 700;
  border-radius: 999px;
  padding: 2px 9px;
  margin-left: 8px;
  vertical-align: middle;
  background: #FEF3C7;
  color: #92400E;
}

.huom {
  font-size: 12px;
  color: #B45309;
  margin-top: 8px;
}

.tarj {
  display: flex;
  gap: 8px;
  align-items: flex-end;
  flex-wrap: wrap;
}

.tarj input {
  width: 130px;
  font-size: 20px;
  font-weight: 700;
  text-align: right;
}

.ero {
  font-size: 13px;
  margin-top: 8px;
}

.ero.neg {
  color: #B91C1C;
}

.ero.pos {
  color: #166534;
}

.vienti {
  display: flex;
  gap: 10px;
  margin-top: 14px;
  flex-wrap: wrap;
  align-items: center;
}

.lisat {
  margin: 8px 0 0 106px;
  display: flex;
  gap: 10px;
  align-items: flex-end;
  flex-wrap: wrap;
  padding-top: 8px;
  border-top: 1px dashed #E3E5E8;
}

[hidden] {
  display: none !important;
}

@media (max-width: 760px) {
  .yht {
    grid-template-columns: 1fr;
  }
  .r2, .sel, .lisat {
    margin-left: 0;
  }
  .badge {
    flex-basis: 74px;
  }
}
#osat {
  margin: 0 0 10px;
}

.osarivi {
  display: flex;
  gap: 10px;
  align-items: center;
  flex-wrap: wrap;
}

.osavihje {
  color: #9CA3AF;
  font-size: 12px;
}

.tabit {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  border-bottom: 2px solid #231F20;
  margin-bottom: 10px;
}

.tab {
  border: 1px solid #E3E5E8;
  border-bottom: 0;
  background: #F3F4F6;
  border-radius: 8px 8px 0 0;
  padding: 7px 12px;
  font: inherit;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  color: #4B5563;
}

.tab.on {
  background: #231F20;
  color: #fff;
  border-color: #231F20;
}

.tab small {
  font-weight: 400;
  margin-left: 8px;
  opacity: 0.85;
  font-variant-numeric: tabular-nums;
}

.tab.plus {
  background: #fff;
  border-style: dashed;
  color: #6B7280;
}

.osainfo {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  align-items: flex-end;
  margin: 0 0 10px;
}

.osan {
  width: 280px;
}

.linkki {
  border: 0;
  background: transparent;
  color: #B4232A;
  font: inherit;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  padding: 6px 0;
}

.linkki.oik {
  margin-left: auto;
}

.yt {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
  font-variant-numeric: tabular-nums;
}

.yt th, .yt td {
  padding: 8px;
  border-bottom: 1px solid #E3E5E8;
  text-align: right;
}

.yt th {
  font-size: 11px;
  color: #6B7280;
  text-transform: uppercase;
  letter-spacing: 0.03em;
}

.yt th:first-child, .yt td:first-child {
  text-align: left;
}

.yt tfoot td {
  font-weight: 700;
  border-bottom: 0;
}

.pohja {
  font-weight: 600;
  background: #E0DEDE;
  border: 0;
  padding: 8px 10px;
  cursor: pointer;
}

#kortti::before {
  content: "Hintalaskuri";
  display: block;
  color: #B4232A;
  font-size: 20px;
  font-weight: 700;
  line-height: 1.4;
  margin-bottom: 12px;
}

.head {
  justify-content: flex-end;
  margin-top: -40px;
  min-height: 28px;
}

