// ---- Laskenta: samat kaavat kuin kannan rivit_hinnoiteltu-näkymässä ----
function num(v) {
  if (v === null || v === undefined) return null;
  const s = String(v).replace(/\s/g, '').replace(',', '.');
  if (s === '') return null;
  const n = Number(s);
  return isFinite(n) ? n : null;
}
function r2(x) {
  return Math.round((x + Number.EPSILON) * 100) / 100;
}
function r4(x) {
  return Math.round((x + Number.EPSILON) * 10000) / 10000;
}
function fmt(x, d) {
  if (x === null || x === undefined || !isFinite(x)) return '–';
  return Number(x).toLocaleString('fi-FI', {
    minimumFractionDigits: d ?? 2,
    maximumFractionDigits: d ?? 2
  });
}
function eur(x) {
  return fmt(x, 2) + ' €';
}
function kayttoLeveys(W, D) {
  return W - (num(D.asetukset.reuna) ?? 70);
}
function ladoRulla(kaytto, w, h, n, vali, saaKaantaa) {
  const v = [];
  const yrita = (poikki, pitkin, k) => {
    const per = Math.floor((kaytto + vali) / (poikki + vali));
    if (per < 1) return;
    const riv = Math.ceil(n / per);
    v.push({
      per,
      riv,
      mm: riv * (pitkin + vali),
      kaannetty: k
    });
  };
  yrita(w, h, false);
  if (saaKaantaa && w !== h) yrita(h, w, true);
  if (!v.length) return null;
  v.sort((a, b) => a.mm - b.mm);
  return v[0];
}
function ladoLevy(L, P, w, h, n, vali, saaKaantaa) {
  const g = (a, b) => Math.floor((L + vali) / (a + vali)) * Math.floor((P + vali) / (b + vali));
  let per = g(w, h),
    k = false;
  if (saaKaantaa) {
    const p2 = g(h, w);
    if (p2 > per) {
      per = p2;
      k = true;
    }
  }
  if (per < 1) return null;
  return {
    per,
    levyja: Math.ceil(n / per),
    kaannetty: k
  };
}
// materiaalirivin menekki: q = hinnoiteltava määrä, kq = koneen läpi kulkeva määrä, osto = q on ostoyksikköinä
function menekki(r, D) {
  const m = r.mat;
  if (!m) return {
    q: 0,
    kq: 0,
    sel: ''
  };
  if (r.tila !== 'mitat' || m.ky !== 'm' && m.ky !== 'm2') {
    const q0 = num(r.maara) || 0;
    return {
      q: q0,
      kq: r.osto ? q0 * m.ek : q0,
      osto: !!r.osto,
      sel: ''
    };
  }
  const w = num(r.w),
    h = num(r.h),
    n = num(r.kpl) || 0,
    vali = num(r.vali) ?? num(D.asetukset.vali) ?? 5;
  if (!w || !h || !n) return {
    q: 0,
    kq: 0,
    sel: 'Anna leveys, korkeus ja kappalemäärä.'
  };
  if (m.ky === 'm') {
    const kl = kayttoLeveys(m.lev, D),
      l = ladoRulla(kl, w, h, n, vali, r.kaanna !== false);
    if (!l) return {
      q: 0,
      kq: 0,
      virhe: true,
      sel: 'Ei mahdu ' + m.lev + ' mm rullan tulostusleveydelle ' + kl + ' mm. Paneloitava työ: vaihda syöttötavaksi Menekki.'
    };
    const jm = Math.ceil(l.mm / 10 - 1e-9) / 100;
    return {
      q: jm,
      kq: jm,
      sel: l.per + ' rinnakkain × ' + l.riv + ' riviä' + (l.kaannetty ? ' (käännettynä)' : '') + ' → ' + fmt(jm, 2) + ' jm · rulla ' + m.lev + ' mm, tulostusleveys ' + kl + ' mm'
    };
  }
  const l = ladoLevy(m.lev, m.pit, w, h, n, vali, r.kaanna !== false);
  if (!l) return {
    q: 0,
    kq: 0,
    virhe: true,
    sel: 'Ei mahdu levylle ' + m.lev + ' × ' + m.pit + ' mm.'
  };
  const netto = Math.round(w * h * n / 1e4) / 100;
  if (r.kokolevyt) return {
    q: l.levyja,
    kq: netto,
    osto: true,
    sel: l.per + ' kpl / levy → ' + l.levyja + ' kokonaista levyä (' + fmt(l.levyja * m.ek, 2) + ' m²), kappaleiden ala ' + fmt(netto, 2) + ' m²'
  };
  return {
    q: netto,
    kq: netto,
    sel: l.per + ' kpl / levy → tarvitaan ' + l.levyja + ' levy' + (l.levyja > 1 ? 'ä' : '') + ', veloitetaan kappaleiden ala ' + fmt(netto, 2) + ' m² + hukka'
  };
}
function tunnit(r, kentta) {
  const v = num(r[kentta]);
  if (v === null) return null;
  return r.aikatila === 'h' ? v : v / 60;
}
function aikaSeuraa(r, rivit) {
  if (r.tyyppi !== 'kone' || !r.linkki || r.kasin) return false;
  if (r.lukittu && r.db) return r.db.yks === 'h';
  const s = rivit ? rivit.find(x => x.id === r.linkki) : null;
  return !!(r.kone && r.kone.nop > 0 && s && s.mat && (s.mat.ky === 'm' || s.mat.ky === 'm2'));
}
function seurattuToteuma(r, D, rivit) {
  if (aikaSeuraa(r, rivit)) return null;
  const s = r.linkki && !r.kasin && rivit ? rivit.find(x => x.id === r.linkki) : null;
  if (!s || !s.mat) return null;
  const mt = num(s.toteuma);
  if (mt === null) return null;
  const mk = s.lukittu && s.db ? null : menekki(s, D),
    mq = mk ? mk.q : s.db.q,
    fq = r.lukittu && r.db ? r.db.q : (mk || menekki(s, D)).kq;
  if (!(mq > 0)) return null;
  return r4(fq * mt / mq);
}
function laskeRivi(r, D, rivit) {
  const a = D.asetukset;
  let q = 0,
    yh = 0,
    kust = 0,
    hinta = 0,
    hukka = null,
    kate = null,
    yks = '',
    sel = '',
    virhe = false,
    varo = '',
    seuraa = false,
    osto = false,
    aikaS = false,
    alM = null;
  if (r.lukittu && r.db) {
    // lukittu rivi: hinnat tulevat kannasta jäädytettyinä
    return {
      q: r.db.q,
      yks: r.db.yks,
      yh: r.db.yh,
      kust: r.db.kust,
      hinta: r.db.hinta,
      hintaT: r.db.hintaT,
      kustT: r.db.kustT,
      hukka: r.db.hukka,
      kate: r.db.kate,
      sel: '',
      virhe: false,
      varo: '',
      seuraa: !!r.linkki && !r.kasin,
      osto: !!r.osto,
      lukittu: true
    };
  }
  if (r.tyyppi === 'materiaali') {
    const m = r.mat;
    if (m) {
      const mk = menekki(r, D);
      q = mk.q;
      sel = mk.sel;
      virhe = !!mk.virhe;
      osto = !!mk.osto;
      yks = osto ? m.oy : m.ky;
      yh = osto ? m.hh : m.kh;
      hukka = osto ? null : num(r.hukka) ?? m.hukka ?? a.hukka;
      kate = num(r.kate) ?? m.kate ?? a.kate;
      kust = q * yh / (osto ? 1 : 1 - hukka / 100);
      hinta = kust / (1 - kate / 100);
      if (m.ky === 'm') alM = osto ? Number(m.ek) || 1 : 1;
    }
  } else if (r.tyyppi === 'oma') {
    q = num(r.maara) || 0;
    yh = num(r.yh) || 0;
    yks = r.yks || 'kpl';
    hukka = num(r.hukka) ?? a.hukka;
    kate = num(r.kate) ?? a.kate;
    kust = q * yh / (1 - hukka / 100);
    hinta = kust / (1 - kate / 100);
  } else if (r.tyyppi === 'kone') {
    const k = r.kone,
      lahde = r.linkki && !r.kasin && rivit ? rivit.find(x => x.id === r.linkki) : null;
    if (k && lahde && k.nop > 0 && lahde.mat && (lahde.mat.ky === 'm' || lahde.mat.ky === 'm2')) {
      seuraa = true;
      aikaS = true;
      yks = 'h';
      yh = k.aste > 0 ? k.kust / (k.aste / 100) : 0;
      kate = num(r.kate) ?? k.kate;
      const w = num(lahde.w),
        h = num(lahde.h),
        n = num(lahde.kpl);
      if (lahde.tila === 'mitat' && w > 0 && h > 0 && n > 0) {
        const matka = 2 * (w + h) * n,
          s = matka / k.nop + n * (k.ka || 0) + (k.as || 0) * 60;
        q = r4(s / 3600);
        sel = 'Leikkuumatka ' + fmt(matka / 1000, 2) + ' m, nopeus ' + fmt(k.nop, 0) + ' mm/s' + (k.ka ? ' + ' + fmt(k.ka, 0) + ' s/kpl' : '') + (k.as ? ' + asetus ' + fmt(k.as, 0) + ' min' : '') + ' → ' + fmt(s / 60, 1) + ' min × ' + fmt(yh, 2) + ' €/h';
        if (!k.kust) varo = 'Koneen tuntikustannus on 0 € – rivi ei vielä vaikuta hintaan.';
      } else {
        sel = '';
        varo = 'Leikkuuaikaa ei voi laskea ilman mittoja – valitse Oma aika ja anna aika.';
      }
      kust = q * yh;
      hinta = kust / (1 - kate / 100);
