  if(!d||d.tid!==tid){ if(lataaPyydetty!==tid){ lataaPyydetty=tid; asetaTila('ladataan'); A.triggerEvent('onLataa'); } return; }
  if(S.tid===tid&&S.haettu===d.haettu) return;
  const taysi=S.tid!==tid; S.tid=tid; S.haettu=d.haettu; lataaPyydetty=null;
